<#
  Fix-LighterPhotoMapAndButton.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  PART 1 - PACKAGE PHOTO: NO MORE ANALYSIS, JUST THE PHOTO + MANUAL SIZE
  src\app\send-package\step-2\page.jsx no longer calls the server-side
  Claude vision estimate (a paid API call per photo) or the client-side
  TensorFlow.js + COCO-SSD fallback (a multi-MB on-device model that was
  genuinely struggling on lower-end phones). The photo's only job now is
  letting the rider see what they're picking up. The manual size buttons
  already existed as an override before this change - they're now simply
  the only path, which is instant and free on every device. Cleaned out
  all the dead state this left behind (estimating/sizeSource/
  estimateReasoning/oversizedWarning) and the helper function that only
  fed the removed API call. src\utils\clientSizeEstimate.js and
  src\app\api\estimate-package\route.js are left in place but fully
  unused now - harmless, safe to delete later if you want, not touched by
  this script.

  PART 2 - MAP LOADING STATES + ONE MORE EAGER LOAD FOUND
  Added src\components\MapSkeleton.jsx - a lightweight shimmer+pin
  placeholder, sized to match the real map so there's no layout jump -
  and wired it into every place a map lazy-loads (previously they showed
  nothing at all while the Mapbox chunk downloaded and the WebGL context
  initialized, both of which take a real moment on a weaker phone):
  rider active-job, ops-terminal live orders.

  Also found: src\app\dashboard\page.jsx (the vendor dashboard) was
  importing react-map-gl STATICALLY at the top of the page - not lazy at
  all - so the full Mapbox bundle loaded eagerly the instant a vendor
  opened their dashboard. Extracted the map into
  src\components\VendorDashboardMap.jsx and made it lazy like everywhere
  else in the app, which also now properly makes use of the existing
  warmMapBundle.js prefetch helper that was already in the codebase for
  this exact complaint.

  PART 3 - INSTALL APP BUTTON, SMALLER
  src\components\InstallAppButton.jsx: default padding/text size reduced
  (px-5 py-3 text-xs -> px-3.5 py-2 text-[10px]), smaller icon, shorter
  label ("Install" instead of "Install App"). src\app\page.js: removed
  the homepage's manual size override, since the component's own default
  is now already compact enough on its own.

  One open item: "the sizes you use sometimes are fitted to phones with a
  bit larger area" was general feedback, not tied to a specific element
  beyond the install button - if there's another specific spot that still
  feels oversized on your device, point me at it and I'll fix that one
  directly rather than me guessing across the whole app.

  Writes full file content (base64-encoded, written as raw bytes - no
  PowerShell string-escaping of JS/JSX, no BOM-injection risk). Backs up
  every existing file it touches to .fix-backup-lighter-photo-map\ first.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-LighterPhotoMapAndButton.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-lighter-photo-map"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

if (-not (Test-Path -LiteralPath (Join-Path $root "src\app"))) {
    Write-Host "ERROR: src\app not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Path $destParent -Force | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FileFromBase64($relPath, $b64) {
    $full = Get-FullPath $relPath
    $targetParent = Split-Path $full -Parent
    if (-not (Test-Path -LiteralPath $targetParent)) { New-Item -ItemType Directory -Path $targetParent -Force | Out-Null }
    Backup-Path $full
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  WROTE: $relPath" -ForegroundColor Green
}

Write-Host "`nApplying lighter photo upload, map loading states, and smaller install button:" -ForegroundColor Cyan

$b64_STEP2 = ""
Write-FileFromBase64 "src\app\send-package\step-2\page.jsx" $b64_STEP2

$b64_MAPSKELETON = ""
Write-FileFromBase64 "src\components\MapSkeleton.jsx" $b64_MAPSKELETON

$b64_VENDORMAP = ""
Write-FileFromBase64 "src\components\VendorDashboardMap.jsx" $b64_VENDORMAP

$b64_VENDORDASH = ""
Write-FileFromBase64 "src\app\dashboard\page.jsx" $b64_VENDORDASH

$b64_ACTIVEJOB = ""
Write-FileFromBase64 "src\app\rider\(main)\active-job\page.jsx" $b64_ACTIVEJOB

$b64_LIVEORDERS = ""
Write-FileFromBase64 "src\app\ops-terminal\orders\LiveOrdersFeed.jsx" $b64_LIVEORDERS

$b64_INSTALLBTN = ""
Write-FileFromBase64 "src\components\InstallAppButton.jsx" $b64_INSTALLBTN

$b64_HOMEPAGE = ""
Write-FileFromBase64 "src\app\page.js" $b64_HOMEPAGE

Write-Host "`nDone. Backups saved under .fix-backup-lighter-photo-map\" -ForegroundColor Cyan
Write-Host "Next: npm run build (or your usual dev command), then commit, push, and redeploy." -ForegroundColor Cyan
